definition.raw:
A $\mathbb{Q}$-representative of a morphism of spectra $g : Y \rightarrow L_1 S /p^\infty$ is a morphism $f : Y \rightarrow KU_\mathbb{Q}$ which makes the following diagram commute
	\begin{eqnarray}
\label{eqn:KU-commutative-ad}
 \xymatrix{
Y
\ar[r]^g
\ar[d]_f
&
L_1 S /p^\infty
\ar[d]^\alpha
\\
KU_\mathbb{Q}
\ar[r]_q
&
KU/p^\infty.
}
\end{eqnarray}

\cite{HS_comod}
\label{def:Landweber_exact}
A  morphism $b : A \rightarrow B$ is Landweber
exact with respect to $(A,\Gamma)$ if the functor $B\otimes_A - : \Gamma \hspace{-.2em}-\hspace{-.2em} \mathrm{Comod}
\rightarrow B \hspace{-.2em}-\hspace{-.2em} \mathrm{Mod}$ is exact.

theorem.raw:
\label{thm:fprime}
	The $f'$-invariant on the primitives of ${Ell}_* (\mathbb{C} \mathbf{P}^\infty_0\wedge \mathbb{C} \mathbf{P}^\infty_0) $ is determined by
\[
f'' (p_s \otimes p_t)
 =
\Big[
 \overline{B}^{Ell}_{s+1}\overline{B}^{KU} _{t+1}
  + \overline{B}^{KU}_{s+1}\overline{B}^{KU}
_{t+1}\frac{\gamma^{s+1}(1- \gamma^{t+1}) }{\gamma^{s+t+2}-1}
\Big],
\]
where $s, t$ are natural numbers and $
 \overline{B}^{Ell}_{s+1}\overline{B}^{KU} _{t+1}  + \overline{B}^{KU}_{s+1}\overline{B}^{KU}
_{t+1}\frac{\gamma^{s+1}(1- \gamma^{t+1}) }{\gamma^{s+t+2}-1}
$ is considered as an element of ${Ell}_*KU \otimes \mathbb{Q}$.

lemma.raw:
\label{lem:iota2_rho1}
	Let $x$ be a $2$-cocycle in $M_k^{(2)}$ which represents a class $$[x] \in \mathrm{Ext}^{2, *} _{{Ell}_* {Ell}} ({Ell}_*, {Ell}_*).$$ Then
	\begin{enumerate}
		\item
		there exists an element $c \in M_k^{(1)}$ and an integer $n$ such that $\delta^1 c = nx$;
		\item
		the invariant $\iota^2 [x]$ is represented by the element $\frac{1}{n}\overline{\rho}^1 (c) \in \mathfrak{D}_\mathbb{Q}$.
	\end{enumerate}

proposition.raw:
\label{prop:represent-ad}
Let $Y$ be a spectrum such that $KU ^*_{(p)} Y$ is a finitely-generated free $KU_{(p)*}$-module  and
$KU^{\mathrm{odd}}_{(p)}Y=0$. Then
\begin{enumerate}
	\item
	the morphism $[Y, L_1 S /p^\infty ] \rightarrow [Y, KU/p^\infty]$ is injective;
	\item
	any morphism $g : Y \rightarrow L_1 S /p^\infty$ admits a $\mathbb{Q}$-representative;
\item
a morphism $f: Y \rightarrow KU_\mathbb{Q}$ such that $(\psi^\gamma -1) f$ lies in the image of $KU^0_{(p)}Y \rightarrow
KU^0_\mathbb{Q} Y$ is the $\mathbb{Q}$-representative of a unique morphism $g : Y \rightarrow L_1 S/p^\infty$.
\end{enumerate}

\label{prop:f,g-Landweber}
Let $E$ be a Landweber exact complex oriented ring spectrum and $g: Y \rightarrow L_1 S /p^\infty$ be a morphism of spectra which admits a $\mathbb{Q}$-representative $f: Y \rightarrow KU_\mathbb{Q}$. Then
\begin{enumerate}
	\item
	the morphism
$E_* (g) : E_* Y \rightarrow E_* (L_1 S /p^\infty)$ is determined by $E_* (f)$ via the commutative diagram of morphisms of  $E_*E$-comodules:
\[
	\xymatrix{
E_* Y
\ar[r]^{E_* (g)}
\ar[d]_{E_*(f)}
&
E_*/p^\infty [v_1^{-1}]
\ar@{^(->}[d]
\\
E_* KU \otimes \mathbb{Q}
\ar@{->>}[r]
&
E_* KU/p^\infty .
}
\]
\item
The morphism $E_* (f)$  is determined by the morphism of $KU_*$-modules $\tilde{f}_* : KU_*  Y \rightarrow KU_*
\otimes \mathbb{Q}$ induced by $f$.
\end{enumerate}

\label{prop:rho_rat}
The morphism $\overline{\rho}^1 \otimes \mathbb{Q}$ is the morphism of right ${Ell}_* \otimes \mathbb{Q}$-modules:
\[
q^0 \otimes {Ell}_*  \otimes \mathbb{Q} :
{Ell}_* \otimes {Ell}_* \otimes \mathbb{Q}
\cong
{Ell}_* {Ell} \otimes \mathbb{Q}
\rightarrow
 KU_* {Ell}\otimes \mathbb{Q}
 \cong
KU_* \otimes  {Ell}_* \otimes \mathbb{Q}
\]

\label{prop:ext-cobar}
\cite[Lemma A.1.1.6, Corollary A1.2.12]{ravenel_green}
Let $X$ be an $A$-projective  $\Gamma$-comodule and $M$ be a  $\Gamma$-comodule. Then $ \mathrm{Ext}^\bullet_\Gamma (X, M)$ can be calculated by a resolution of $M$ of the from $M \rightarrow J^\bullet$, where each $J^k$ is relatively injective.
 In particular, $ \mathrm{Ext}^\bullet_\Gamma (X, M)$ is naturally isomorphic to the cohomology
of the cocomplex $\mathrm{Hom}_\Gamma (X, \tilde{D}^\bullet_\Gamma M)$, which has terms
$\mathrm{Hom}_A (X, \Gamma^{\otimes_A s }\otimes _A M)$.

\label{prop:cocycle-canonical-splitting}
Let
\begin{eqnarray}
\label{eqn:ses-comod}
0 \rightarrow M
\rightarrow
\mathcal{E}
\stackrel{p}{\rightarrow}
X
\rightarrow
0
\end{eqnarray}
be a short exact sequence of $\Gamma$-comodules, in which $X$ is $A$-projective.

Then, for any choice of section $\sigma : X \rightarrow \mathcal{E}$, with associated
retract  $r :\mathcal{E}\rightarrow M$,  the composite:
\[
X \stackrel{- \sigma}{\rightarrow}
\mathcal{E}
\stackrel{\psi_{\mathcal{E}}}{\rightarrow}
\Gamma \otimes _A \mathcal{E}
\stackrel{\Gamma \otimes r}{\rightarrow}
\Gamma \otimes_A M
\]
is a cocycle which represents the extension class $\partial 1_X$, which corresponds to the short exact sequence (\ref{eqn:ses-comod}). A different choice of splitting as $A$-modules gives rise to a cohomologous cocycle.

\cite{HS_comod}
	If $b : A  \rightarrow B$ is Landweber exact with respect to $(A, \Gamma)$, then $(B, \Gamma_B)$ is a flat Hopf algebroid and $B \otimes_A -$ induces an exact functor $B\otimes_A - : \Gamma \hspace{-.2em}-\hspace{-.2em} \mathrm{Comod}
\rightarrow \Gamma_B \hspace{-.2em}-\hspace{-.2em} \mathrm{Comod}$.

remark.raw:
The universal Weierstrass curve over the ring of holomorphic modular forms ${MF}$ is not an elliptic curve;
however, the associated formal group law is
defined, since the curve is smooth at the identity section. Similarly for  the Tate curve.

