	For $f: X \rightarrow \Gamma \otimes_A M $ a morphism of left
$A$-modules, write $_Bf_C : B \otimes _A X \rightarrow {_B\Gamma_C} \otimes _A M$ for the morphism of left $B$-modules:
\[
	B \otimes _A X
\stackrel{B \otimes f } {\rightarrow}
B \otimes _A \Gamma \otimes _A M
\stackrel{B \otimes A \otimes c \otimes M}{\rightarrow}
{_B\Gamma_C} \otimes _A M.
\]
\end{nota}

\begin{exam}
 Let $X, M$ be as in Proposition \ref{prop:ext-cobar};	a cocycle $\kappa : X \rightarrow \Gamma \otimes_A M$  induces a
morphism $_B \kappa _C : B\otimes_A X \rightarrow {_B\Gamma_C} \otimes _A M \cong {_B\Gamma_C} \otimes_C (C \otimes_A M)$.
\end{exam}

